+import { AppError } from "../errors.js";
+
+/** Finds the identity for an API key, rejecting missing or unknown keys. */
+export function authenticate(store, key) {
+  const identity = key && store.data.apiKeys.find((entry) => entry.key === key);
+  if (!identity) throw new AppError("unauthorized");
+  return identity;
+}
+
+/** Checks the role against the requested method and route. */
+export function authorize(identity, method, path) {
+  if (identity.role === "manager") return;
+  if (["viewer", "cook"].includes(identity.role) && method === "GET" && path !== "/audit") return;
+  if (identity.role === "cook" && method === "POST" && (
+    /^\/recipes\/[^/]+\/cook$/.test(path) ||
+    /^\/batches\/[^/]+\/waste$/.test(path) ||
+    /^\/stocktakes\/[^/]+\/counts$/.test(path) || path === "/temperatures"
+  )) return;
+  throw new AppError("forbidden");
+}
+
+/** Appends the outcome of a request that saved data. */
+export function recordAudit(store, entry) {
+  store.data.audit.push({ ...entry });
+}
+
+/** Lists audit entries newest first, including reverse order for equal times. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse().sort((a, b) => b.time.localeCompare(a.time));
+}
