diff --git a/tests/access.test.js b/tests/access.test.js
new file mode 100644
index 0000000..b4b6bf1
--- /dev/null
+++ b/tests/access.test.js
@@ -0,0 +1,85 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { createApp } from "../src/http/server.js";
+import { openStore } from "../src/db/store.js";
+import { migrate } from "../src/db/migrations.js";
+import { fresh, seed, NOW } from "./helpers.js";
+
+const headers = (role) => ({ Authorization: `Bearer seed-${role}` });
+
+test("missing and unknown keys get 401; role failures get 403", async () => {
+  const store = fresh();
+  const handle = createApp(store);
+  for (const authorization of [undefined, "Bearer unknown", "Basic seed-manager", "Bearer "]) {
+    const response = await handle({ path: "/items", headers: { authorization } });
+    assert.equal(response.status, 401);
+    assert.equal(response.body.error.code, "unauthorized");
+  }
+  for (const role of ["viewer", "cook"]) {
+    assert.equal((await handle({ path: "/items", headers: headers(role) })).status, 200);
+    assert.equal((await handle({ path: "/audit", headers: headers(role) })).status, 403);
+    const denied = await handle({ method: "POST", path: "/orders", headers: headers(role) });
+    assert.equal(denied.status, 403);
+    assert.equal(denied.body.error.code, "forbidden");
+  }
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: headers("viewer") })).status, 403);
+  assert.deepEqual(store.data.audit, []);
+});
+
+test("cooks can perform only the four kitchen writes", async () => {
+  const store = fresh();
+  const handle = createApp(store, { clock: () => NOW });
+  const take = await handle({ method: "POST", path: "/stocktakes", headers: headers("manager"), body: { location: "dry" } });
+  const writes = [
+    ["/recipes/1/cook", { portions: 4 }],
+    ["/batches/1/waste", { qty: 0.1 }],
+    ["/temperatures", { location: "fridge", celsius: 3 }],
+    [`/stocktakes/${take.body.id}/counts`, { batchId: 1, counted: 2 }],
+  ];
+  for (const [path, body] of writes) {
+    const response = await handle({ method: "POST", path, body, headers: headers("cook") });
+    assert.ok(response.status < 300);
+  }
+  for (const path of ["/stocktakes", `/stocktakes/${take.body.id}/finish`, "/prices", "/jobs/nightly"]) {
+    assert.equal((await handle({ method: "POST", path, headers: headers("cook") })).status, 403);
+  }
+  const audit = await handle({ path: "/audit", headers: headers("manager") });
+  assert.equal(audit.body.length, 5);
+  assert.deepEqual(audit.body[0], { time: new Date(NOW).toISOString(), name: "Seed cook", method: "POST", path: writes[3][0], status: 200 });
+  assert.equal(audit.body.at(-1).status, 201);
+  assert.equal(JSON.stringify(audit.body).includes("seed-cook"), false);
+});
+
+test("audit entries survive reopening and a write saves once", async () => {
+  const dir = mkdtempSync(join(tmpdir(), "larder-access-"));
+  try {
+    const file = join(dir, "db.json");
+    writeFileSync(file, JSON.stringify(seed()));
+    const store = openStore(file);
+    let saves = 0;
+    const save = store.save.bind(store);
+    store.save = () => { saves++; save(); };
+    const handle = createApp(store);
+    await handle({ method: "POST", path: "/temperatures", headers: headers("cook"), body: { location: "fridge", celsius: 4 } });
+    assert.equal(saves, 1);
+    const reopened = openStore(file);
+    assert.equal(reopened.data.audit.length, 1);
+    assert.equal(reopened.data.temperatures.length, 3);
+  } finally {
+    rmSync(dir, { recursive: true, force: true });
+  }
+});
+
+test("schema 2 migration preserves existing access data and defaults to no keys", () => {
+  const old = seed();
+  old.schemaVersion = 2;
+  assert.deepEqual(migrate(old).apiKeys, old.apiKeys);
+  delete old.apiKeys;
+  delete old.audit;
+  const migrated = migrate(old);
+  assert.deepEqual(migrated.apiKeys, []);
+  assert.deepEqual(migrated.audit, []);
+});
